// in-memory DB
const MOCK_DB = {
  // 판매거래처
  "/order/sellercustomer": [
    {
      cusNo: 1,
      cusComp: "판매처 A",
      cusName: "홍길동",
      cusEmail: "a@test.com",
      cusPhone: "010-1111-2222",
      cusAddr: "서울 강남구"
    }
  ],
  // 상품주문서
  "/order/orderlist": [
    {
      orderNo: 1,
      orderDate: "2025-10-02",
      cusComp: "판매처 A",
      itemName: "완제품 A",
      orderQty: 19,
      orderPrice: 300000,
      orderState: "승인대기",
      orderDeliState: "납품대기",
      deliveryDate: "2025-10-24",
      cusAddr: "주소",
      totalPrice: 5700000
    },
  ],

  // 주문완료현황
  "/order/completed": [
    // 납품완료된 것들이 여기로 이동
  ],

  // 구매거래처
  "/buyer/buyercustomer": [
    {
      buyerNo: 1,
      buyerComp: "구매처 A",
      buyerName: "강감찬",
      buyerEmail: "a@buyer.com",
      buyerPhone: "010-5555-1111",
      buyerAddr: "대전 유성구"
    }
  ],

  // 부품
  "/buyer/partlist": [
    {
      partNo: 1,            // 일련번호 / PK
      partName: "부품 A",    // 부품명
      buyerComp: "구매처 A", // 구매처명
      partCode: "01",       // 부품코드
      partSpec: "2*3*4",    // 부품규격
      partPrice: 20000      // 부품단가
    },
  ],

  // 부품발주
  "/buyer/partorder": [
    {
      poNo: 1,
      buyerComp: "구매처 A",
      partName: "부품 A",
      poQty: 50,
      poPrice: 3000,
      poState: "입고대기",
      poDate: "2025-10-01",
      buyerAddr: "대전 유성구"
    },
  ],

  // 부품재고
  "/stock/partstocks": [
    {
      poNo: 1,
      buyerComp: "구매처 A",
      partName: "부품 A",
      stockQty: 50,             // 여기서 stockQty는 poQty에서 온다
      partPrice: 3000,
      lastInDate: "2025-10-01",
    },
  ],

  // 생산
  "/plan/planlist": [
    {
      planNo: 1,
      itemName: "완제품 A",
      planName: "A-10월 생산",
      planQty: 100,
      planState: "생산중"
    },
  ],

  // BOM
  "/plan/bom": [
    {
      bomId: 1,
      itemName: "완제품 A",
      partName: "부품 A",
      qtyPerItem: 2
    }
  ],

  // 생산완료재고
  "/stock/item": [
    {
      itemNo: 1,
      itemName: "완제품 A",
      isQty: 37,
      itemPrice: 15000,
      totalValue: 555000,
      lastUpdate: "2025-10-03",
    },
  ],
};

// path마다 PK를 뭐로 쓸지
const META = {
  "/order/orderlist": { key: "orderNo" },
  "/order/completed": { key: "orderNo" },
  "/buyer/partorder": { key: "poNo" },
  "/buyer/buyercustomer": { key: "buyerNo" },
  "/order/sellercustomer": { key: "cusNo" },
  "/plan/planlist": { key: "planNo" },
  "/plan/bomlist": { key: "bomId" },
  "/plan/itemlist": { key: "itemNo" },
  "/stock/item": { key: "itemNo" },
  "/stock/partstocks": { key: "stockNo" },
};

// 유틸: 경로 맞춰서 배열 꺼내기
function getTable(path) {
  if (!MOCK_DB[path]) {
    console.warn("[mockBackend] no mock data for", path);
    MOCK_DB[path] = [];
  }
  return MOCK_DB[path];
}

// GET
export function mockGet(path, opts = {}) {
  const table = getTable(path);
  // 방어적으로 복사
  return structuredClone(table);
}

// POST = 새로 추가
export function mockPost(path, body) {
  const table = getTable(path);
  const pk = META[path]?.key;

  if (pk) {
    if (body[pk] === undefined || body[pk] === null) {
      // auto-increment
      const maxId = table.reduce(
        (max, row) => (row[pk] > max ? row[pk] : max),
        0
      );
      body = { ...body, [pk]: maxId + 1 };
    }
  }

  table.push(body);
  return structuredClone(body);
}

// PUT = 수정
export function mockPut(path, body) {
  const table = getTable(path);
  const pk = META[path]?.key;
  if (!pk) return { success: true };

  const id = body[pk];
  MOCK_DB[path] = table.map(row => (row[pk] === id ? { ...row, ...body } : row));
  return structuredClone(body);
}

// DELETE
export function mockDelete(path) {
  // path 형태가 "/order/list/123" 이런 식으로 들어올 수 있으니까
  // 기본 prefix를 떼고 나머지를 ID로 쓴다.
  const match = path.match(/^(.+?)\/([^/]+)$/); 
  if (!match) {
    console.warn("[mockDelete] cannot parse path", path);
    return { success: true };
  }
  const base = match[1]; // "/order/list"
  const idRaw = match[2]; // "123"

  const pk = META[base]?.key;
  if (!pk) return { success: true };

  const id = isNaN(Number(idRaw)) ? idRaw : Number(idRaw);
  const table = getTable(base);

  MOCK_DB[base] = table.filter(row => row[pk] !== id);

  return { success: true };

}

// 상태 값 변경 시 이동
export function moveRowBetweenLists(srcPath, destPath, pkField, pkValue) {
  const srcTable = getTable(srcPath);
  const destTable = getTable(destPath);

  const idx = srcTable.findIndex(row => row[pkField] === pkValue);
  if (idx === -1) return;

  const row = srcTable[idx];

  // 소스에서 삭제
  srcTable.splice(idx, 1);

  // 목적지에 추가
  destTable.push(row);
}
